import assert from 'node:assert/strict';
import {Chess} from '../../../../lib/chess.js';
import {replay} from '../../E070-knight-outposts/code/replay.mjs';
const code=m=>m.from+m.to+(m.promotion||''),values={p:1,n:3,b:3,r:5,q:9,k:0},description=m=>({move:code(m),san:m.san,from:m.from,to:m.to,piece:m.piece,captured:m.captured||null,promotion:m.promotion||null,enPassant:m.isEnPassant(),victim:m.captured?(m.isEnPassant()?m.to[0]+m.from[1]:m.to):null});
// Reconstruct actual history and the entire policy tree; no collector helpers.
export function verifyPanel(input,panel,initial){replay(input,initial);const h=input.history;assert.ok(h&&Array.isArray(h.moves)&&h.moves.length<=1000);let nodes=2;const c=new Chess(h.fen);for(const m of h.moves){assert.equal(c.isGameOver(),false);assert.match(m,/^[a-h][1-8][a-h][1-8][qrbn]?$/);nodes++;c.move(m);}assert.equal(c.fen(),new Chess(input.fen).fen());assert.equal(c.isGameOver(),false);const actor=c.turn(),square=initial.evidence.played.to,supporters=Array.from(new Set(initial.evidence.legalSupport.captures.map(m=>m.from))).sort(),snapshot=()=>{const army=c.board().flat().filter(Boolean).map(t=>({square:t.square,type:t.type,color:t.color})).sort((a,b)=>a.square.localeCompare(b.square));return{fen:c.fen(),army,balance:army.reduce((n,t)=>n+values[t.type]*(t.color===actor?1:-1),0),flags:{mate:c.isCheckmate(),stalemate:c.isStalemate(),insufficient:c.isInsufficientMaterial(),fifty:c.isDrawByFiftyMoves(),threefold:c.isThreefoldRepetition()},checking:c.isCheck()};},legal=()=>c.isGameOver()?[]:c.moves({verbose:true}).sort((a,b)=>code(a).localeCompare(code(b))),claims=[],record=path=>{if(c.isDrawByFiftyMoves()||c.isThreefoldRepetition())claims.push(path.join('/')+'|'+c.fen());};nodes++;const root={state:snapshot(),legal:legal().map(description)},actual=root.legal.find(m=>m.move===input.move);assert.ok(actual&&actual.piece==='n'&&!actual.captured&&!actual.promotion);nodes++;c.move(input.move);nodes++;record([input.move]);const replies=legal(),expected={schema:'E160-complete-outpost-holding-panel-v1',before:root.state.fen,history:input.history,actor,baseline:root.state.balance,square,supporters,initial,root,played:{...actual,state:snapshot()},legal:replies.map(description),branches:[],claimContexts:claims,nodes:0};
  for(const reply of replies){nodes+=3;c.move(code(reply));record([input.move,code(reply)]);const knight=c.get(square)?.type==='n'&&c.get(square)?.color===actor,b={...description(reply),state:snapshot(),legal:[],attempts:[]},options=legal();b.legal=options.map(description);for(const option of options){const d=description(option);let kind=null;if(knight){if(d.from!==square&&!d.captured&&!d.promotion)kind='hold';}else if(reply.captured==='n'&&reply.to===square&&'nbrq'.includes(reply.piece)&&d.piece==='p'&&supporters.includes(d.from)&&d.to===square&&d.captured===reply.piece&&d.victim===square&&!d.promotion)kind='recapture';if(kind===null)continue;nodes+=3;c.move(d.move);record([input.move,code(reply),d.move]);const a={...d,kind,state:snapshot(),legal:[],counters:[]},counters=legal();a.legal=counters.map(description);for(const counter of counters){nodes++;c.move(code(counter));record([input.move,code(reply),d.move,code(counter)]);a.counters.push({...description(counter),state:snapshot()});c.undo();}b.attempts.push(a);c.undo();}expected.branches.push(b);c.undo();}expected.nodes=nodes;assert.deepEqual(panel,expected);return{nodes};
}

