const text={'knight-outpost-holding-policy':'Outpost policy covers every defense: retain the knight and original pawn support through the next counterreply, or make a material-retaining pawn recapture.','knight-ending-outpost-holding-policy':'Knight ending: every defense permits supported outpost retention through the next counterreply or a material-retaining pawn recapture. Longer-term permanence remains unresolved.'};
export function checkWitness(w,result,input){const p=w.panel,a=result.outpostHoldingAnalysis,initial=a.initial;assert.ok(initial?.event);verifyPanel(input,p,initial.event);assert.equal(initial.analysis.status,'proven');assert.equal(initial.analysis.refutation,null);assert.equal(initial.analysis.limit,a.limit-3);const e=initial.event.evidence,initialCost=3+(input.history.moves.length)+e.legalSupport.captures.length+e.replies.length+e.graphs.reduce((n,g)=>n+g.nodes.length+g.edges.length,0);assert.equal(initial.analysis.nodes,initialCost);assert.equal(a.nodes,3+initialCost+p.nodes);assert.equal(a.limit,input.maxOutpostHoldingNodes??50000);assert.ok(['c','d','e','f'].includes(p.square[0]));assert.equal(p.played.state.checking,false);const has=(s,square,type)=>s.army.some(t=>t.square===square&&t.type===type&&t.color===p.actor),alive=s=>Object.values(s.flags).every(v=>v===false),retained=(s,kind)=>kind==='recapture'?has(s,p.square,'p'):has(s,p.square,'n')&&p.supporters.some(square=>has(s,square,'p')&&Math.abs('abcdefgh'.indexOf(square[0])-'abcdefgh'.indexOf(p.square[0]))===1&&Number(square[1])+(p.actor==='w'?1:-1)===Number(p.square[1])),branches=[];
  for(const b of p.branches){const attempts=[];for(const action of b.attempts){const failures=[];if(!alive(action.state))failures.push('response-terminal');if(action.state.balance<p.baseline)failures.push('response-material');if(!retained(action.state,action.kind))failures.push('response-retention');if(action.counters.length===0)failures.push('no-live-counters');for(const counter of action.counters){if(!alive(counter.state))failures.push(counter.move+':terminal');if(counter.state.balance<p.baseline)failures.push(counter.move+':material');if(!retained(counter.state,action.kind))failures.push(counter.move+':retention');}attempts.push({move:action.move,kind:action.kind,passed:failures.length===0,failures});}const successes=attempts.filter(t=>t.passed).map(t=>({move:t.move,kind:t.kind}));branches.push({reply:b.move,attempts,successes,passed:successes.length>0});}const complete=branches.length>0&&branches.filter(b=>b.passed).length===branches.length&&p.claimContexts.length===0,ending=p.root.state.army.filter(t=>!['k','p','n'].includes(t.type)).length===0&&['w','b'].every(color=>p.root.state.army.some(t=>t.color===color&&t.type==='n')),policy={complete,knightEnding:complete&&ending,branches,refutations:branches.filter(b=>!b.passed).map(b=>b.reply),claimContexts:p.claimContexts};assert.deepEqual(w,{experiment:'E160',before:p.before,after:p.played.state.fen,actor:p.actor,played:input.move,panel:p,policy});assert.deepEqual(a.witness,w);assert.equal(result.before,w.before);assert.equal(result.after,w.after);const ids=[];if(complete)ids.push('knight-outpost-holding-policy');if(complete&&ending)ids.push('knight-ending-outpost-holding-policy');const events=ids.map(id=>{assert.ok(text[id].split(/\s+/).length<=24);return{id,text:text[id],qualityClaim:false,evidence:{experiment:'E160',before:w.before,after:w.after,detail:{source:'outpostHoldingAnalysis.witness'}}};});assert.deepEqual(result.events.filter(e=>e.evidence?.experiment==='E160'),events);assert.equal(a.status,events.length?'proven':p.claimContexts.length?'claim-rule-prerequisite':'compared');return true;}
